using System;using System.Collections.Generic;using Game.Components;using Unity.Entities;using Unity.Mathematics;namespace Game.Runtime{internal sealed partial class GeneratedRuntimeSpawnProcessor{
 float _nextRuntimeSpawnRequestProbeAt;readonly List<int> _pendingSpawnRequestIndices=new List<int>();bool _forcePublishNextUpdate;readonly GeneratedRoadMask _skirmishRoads;readonly GeneratedBuildingMask _skirmishBuildings;
 internal GeneratedRuntimeSpawnProcessor(GeneratedRoadMask roads,GeneratedBuildingMask buildings){_skirmishRoads=roads??throw new ArgumentNullException(nameof(roads));_skirmishBuildings=buildings??throw new ArgumentNullException(nameof(buildings));}
 internal bool PublishRequired=>_forcePublishNextUpdate;
 internal void Process(GeneratedConfiguredDefinitionSource definitions,BuildingRuntimeSpawnCompositionSystemHelper spawn,BuildingRuntimeSpawnCompositionSystemHelper.Context context,EntityManager em,Entity boundary,float now,bool forceScan=false){if(float.IsNaN(now)||float.IsInfinity(now))throw new NotSupportedException("Finite original simulation time required");var rows=EnsureBoundaryBuffer<BuildingRuntimeSpawnRequest>(em,boundary);for(int i=0;i<rows.Length;i++){var r=rows[i];if(r.Status!=BuildingRuntimeSpawnRequest.Pending)continue;if(r.RequestKind!=BuildingRuntimeSpawnRequest.KindBuilding||r.AuthoredStartingGrant==0||r.AllowNonBuildableEnemy!=0||r.RotateVertical!=0||r.RequirePreferredOrigin!=0)throw new NotSupportedException("Only original ordinary starting grants admitted");if(em.Exists(r.PlanEntity)&&em.HasComponent<CampaignMissionRuntimeComponent>(r.PlanEntity))throw new NotSupportedException("Active Campaign branch unsupported");if(TryResolveConfiguredBuildingDefinition(definitions,r.BuildingId.ToString(),out var d)&&(!d.SourceMetadataComplete||d.HasRunway||d.IsWall||BuildingBarrierUtilitySystemHelper.IsWallGateDefinition(d)))throw new NotSupportedException("Active wall/runway or incomplete metadata unsupported");}ProcessRuntimeSpawnRequests(definitions,spawn,context,em,boundary,now,forceScan);}
 static DynamicBuffer<T> EnsureBoundaryBuffer<T>(EntityManager entityManager,Entity boundary)where T:struct,IBufferElementData{if(!entityManager.HasBuffer<T>(boundary))entityManager.AddBuffer<T>(boundary);return entityManager.GetBuffer<T>(boundary);}
 static bool IsRegisteredMissionRoadObstruction(EntityManager em,in BuildingRuntimeSpawnRequest request,RuntimeDefinition definition,BuildingRuntimeSpawnCompositionSystemHelper.Context context)=>throw new NotSupportedException("Active mission obstruction unsupported");
 }
 internal static partial class SkirmishEnemyConstructionAdapter{internal static bool IsConstructionRequest(in BuildingRuntimeSpawnRequest r)=>r.RequestKind==BuildingRuntimeSpawnRequest.KindSkirmishPaidConstruction;internal static bool CanProcess(EntityManager em,in BuildingRuntimeSpawnRequest r,out bool defer){throw new NotSupportedException("Active enemy construction unsupported");}internal static bool NativeRectFits(EntityManager em,BuildingRuntimeSpawnRequest r,int2 at,int2 size)=>throw new NotSupportedException("Active enemy construction unsupported");internal static void RecordNativeResult(EntityManager em,BuildingRuntimeSpawnRequest r)=>throw new NotSupportedException("Active enemy construction unsupported");}
 internal sealed class GeneratedRoadMask{readonly GridConfig admitted;readonly bool[] roads,water,sidewalks;internal GeneratedRoadMask(GridConfig grid,bool[] roads,bool[] water,bool[] sidewalks){admitted=grid;int n=checked(grid.Width*grid.Height);foreach(var x in new[]{roads,water,sidewalks})if(x==null||x.Length!=n)throw new NotSupportedException("All source geometry masks required");this.roads=(bool[])roads.Clone();this.water=(bool[])water.Clone();this.sidewalks=(bool[])sidewalks.Clone();}internal void Ensure(EntityManager em,EntityQuery q,GridConfig g){Validate(g);}void Validate(GridConfig g){if(g.Width!=admitted.Width||g.Height!=admitted.Height||g.CellSize!=admitted.CellSize||g.Origin.x!=admitted.Origin.x||g.Origin.z!=admitted.Origin.z)throw new NotSupportedException("Mask/grid identity mismatch");}bool Overlap(bool[] mask,GridConfig g,Vector2Int at,Vector2Int size){Validate(g);for(int y=at.y;y<at.y+size.y;y++)for(int x=at.x;x<at.x+size.x;x++)if(x>=0&&y>=0&&x<g.Width&&y<g.Height&&mask[y*g.Width+x])return true;return false;}internal bool Overlaps(GridConfig g,Vector2Int at,Vector2Int size)=>Overlap(roads,g,at,size);internal bool OverlapsWater(GridConfig g,Vector2Int at,Vector2Int size)=>Overlap(water,g,at,size);internal bool[] GetSidewalks()=>sidewalks;}
 internal sealed class GeneratedBuildingMask{readonly GridConfig admitted;readonly bool[] cells;internal GeneratedBuildingMask(GridConfig g,bool[] cells){if(cells==null||cells.Length!=checked(g.Width*g.Height))throw new NotSupportedException("Authored building mask required");admitted=g;this.cells=(bool[])cells.Clone();}internal bool IsReady=>true;internal void Ensure(EntityManager em,GridConfig g){if(g.Width!=admitted.Width||g.Height!=admitted.Height||g.CellSize!=admitted.CellSize||g.Origin.x!=admitted.Origin.x||g.Origin.z!=admitted.Origin.z)throw new NotSupportedException("Mask/grid identity mismatch");}internal bool Overlaps(GridConfig g,Vector2Int at,Vector2Int size){Ensure(null,g);for(int y=at.y;y<at.y+size.y;y++)for(int x=at.x;x<at.x+size.x;x++)if(x>=0&&y>=0&&x<g.Width&&y<g.Height&&cells[y*g.Width+x])return true;return false;}}
